from fractions import Fraction as Q
from math import factorial,comb
def moment(d,t):
 return Q(0) if d%4 else Q(factorial(d),factorial(d//4))*(-t)**(d//4)
def differentiated_moment(g,r,t):
 return Q(0) if g<r else Q(factorial(g),factorial(g-r))*moment(g-r,t)
checks=0
for t in [Q(1),Q(1,2),Q(5,7)]:
 for N in [1,2,4,8,16]:
  h=t/N
  for g in range(18):
   actual=N*sum((comb(g,a)*moment(a+3,h)*moment(g-a,t-h) for a in range(g+1)),Q(0))
   limit=-24*t*differentiated_moment(g,1,t)
   remainder=144*t*t/N*differentiated_moment(g,5,t)-64*t**3/N**2*differentiated_moment(g,9,t)
   assert actual==limit+remainder
   if g==1:assert actual==-24*t
   if g==5:assert actual-limit==17280*t*t/N
   checks+=1
print(dict(exact_signed_convolution_tests=checks,passed=True,scope='Finite signed polynomial moment and mesh scaling test; the dual-norm proof is separate Lean mathematics'))
